<script setup lang="ts">
import { computed, nextTick, onActivated, onBeforeUnmount, ref, watch } from 'vue';
import { api, ApiError } from '../auth';
import { project, projectId, persistProject, refreshProjects, sync } from '../platform';
import { ask, toast, busyTasks } from '../store';
import { execute } from '../client';
import { downloadJson } from '../execution';
import { aiSettingsRoute, csvForRows } from '../ai-utils.mjs';
import Icon from '../components/Icon.vue';

type RecordValue={id:string;kind:string;provider:string;model:string;createdAt:string;value:any};
const tabs=[['chat','智能对话','ai'],['cases','用例生成','layers'],['data','测试数据工厂','database'],['risk','风险洞察','security']];
const tab=ref('chat'),checking=ref(true),loading=ref(false),busy=ref(false),saving=ref(false),error=ref(''),state=ref<any>();
const chat=ref<RecordValue[]>([]),message=ref(''),pending=ref(''),contextMode=ref('project'),messagesEl=ref<HTMLElement>();
const requirement=ref(''),caseType=ref('auto'),caseCount=ref(6),caseRecord=ref<RecordValue>(),selected=ref<string[]>([]),stage=ref('');
const fields=ref('姓名, 手机号, 邮箱, 身份证, 地址'),dataMode=ref('VALID'),dataCount=ref(5),dataRecord=ref<RecordValue>(),dataView=ref('table');
const riskRecord=ref<RecordValue>();
let controller:AbortController|undefined;
const working=computed(()=>busy.value||saving.value),engine=computed(()=>state.value?.engine||{});
const provider=computed(()=>!engine.value.provider?'远程 AI':String(engine.value.baseUrl||'').includes('deepseek')?'DeepSeek':engine.value.provider==='ANTHROPIC'?'Anthropic':'OpenAI 兼容');
const cases=computed<any[]>(()=>caseRecord.value?.value.cases||[]),imported=computed<string[]>(()=>caseRecord.value?.value.importedCaseIds||[]);
const allSelected=computed({get:()=>cases.value.some(c=>!imported.value.includes(c.id))&&cases.value.filter(c=>!imported.value.includes(c.id)).every(c=>selected.value.includes(c.id)),set:v=>selected.value=v?cases.value.filter(c=>!imported.value.includes(c.id)).map(c=>c.id):[]});
const evidence=computed(()=>state.value?.context),dimensions=computed<any[]>(()=>evidence.value?.dimensions||[]);
const labels:Record<string,string>={NO_DATA:'暂无数据',HIGH:'需优先处理',REVIEW:'需复核',LOW:'暂无已记录失败'};
const typeLabel:Record<string,string>={api:'接口',ui:'UI'};
watch([busy,saving],()=>busyTasks.ai=working.value);
function readTab(){if(location.hash.split('?')[0]==='#/ai'){const value=new URLSearchParams(location.hash.split('?')[1]||'').get('tab');if(tabs.some(t=>t[0]===value))tab.value=value!;}}
function setTab(value:string){tab.value=value;location.hash=`#/ai?tab=${value}`;error.value='';}
function missing(e:unknown){if(e instanceof ApiError&&e.code==='AI_NOT_CONFIGURED'){location.hash=aiSettingsRoute();toast('请先配置 AI API 密钥',true);return true;}return false;}
async function load(){
  if(working.value)return;loading.value=true;error.value='';
  try{
    const settings=await api('platform/settings');
    if(!settings.ai.configured){location.hash=aiSettingsRoute();toast('请先在 AI 引擎设置中配置密钥');return;}
    state.value=await api(`ai/state?projectId=${encodeURIComponent(projectId.value)}`);chat.value=state.value.chat;
    caseRecord.value=state.value.cases?.[0];dataRecord.value=state.value.data?.[0];riskRecord.value=state.value.risk?.[0];selected.value=[];
  }catch(e){if(!missing(e))error.value=(e as Error).message;}finally{checking.value=false;loading.value=false;}
}
async function generate(action:()=>Promise<void>){if(working.value)return;busy.value=true;error.value='';controller=new AbortController();try{await action();}catch(e){if(!missing(e)&&(e as Error).name!=='AbortError')error.value=(e as Error).message;}finally{busy.value=false;stage.value='';pending.value='';}}
async function send(){
  const text=message.value.trim();if(!text)return;
  await generate(async()=>{pending.value=text;message.value='';await nextTick();messagesEl.value?.scrollTo({top:messagesEl.value.scrollHeight});
    try{const result=await api<RecordValue>('ai/chat','POST',{projectId:projectId.value,message:text,context:contextMode.value},controller?.signal);chat.value.push(result);}
    catch(e){message.value=text;throw e;}
    await nextTick();messagesEl.value?.scrollTo({top:messagesEl.value.scrollHeight,behavior:'smooth'});
  });
}
function shortcut(mode:string,text:string){contextMode.value=mode;message.value=text;setTab('chat');}
async function clearChat(){if(!await ask('清空当前账号在此项目的 AI 对话记录？'))return;await generate(async()=>{await api(`ai/chat?projectId=${encodeURIComponent(projectId.value)}`,'DELETE');chat.value=[];});}
async function generateCases(){
  if(!requirement.value.trim())return toast('请填写需求描述或页面 URL',true);
  await generate(async()=>{
    let elements:any[]=[],sourceUrl='';const text=requirement.value.trim();
    if(/^https?:\/\/\S+$/.test(text)&&caseType.value!=='api'){
      sourceUrl=text;stage.value='正在使用真实浏览器分析页面元素…';
      const inspected=await execute<any>('ui/inspect',{url:sourceUrl,variables:{}},controller?.signal);elements=inspected.elements;
    }
    stage.value='正在请求模型设计测试用例…';
    caseRecord.value=await api('ai/cases','POST',{projectId:projectId.value,requirement:requirement.value,type:sourceUrl?'ui':caseType.value,count:Number(caseCount.value),sourceUrl,elements},controller?.signal);
    selected.value=cases.value.map(c=>c.id);toast('用例已生成，请核对后保存');
  });
}
async function importCases(ids:string[]){
  if(!caseRecord.value||!ids.length)return;if(!project.value)return toast('请先创建并选择项目',true);
  saving.value=true;error.value='';
  try{await persistProject();if(sync.error)throw new Error(sync.error);const result=await api<any>(`ai/records/${caseRecord.value.id}/import`,'POST',{caseIds:ids});await refreshProjects();toast(`已保存 ${result.added} 条用例到项目`);}
  catch(e){error.value=(e as Error).message;}finally{saving.value=false;}
}
async function generateData(){await generate(async()=>{dataRecord.value=await api('ai/data','POST',{projectId:projectId.value,fields:fields.value,mode:dataMode.value,count:Number(dataCount.value)},controller?.signal);});}
async function interpret(){await generate(async()=>{riskRecord.value=await api('ai/risk','POST',{projectId:projectId.value},controller?.signal);});}
async function copy(value:unknown){try{await navigator.clipboard.writeText(typeof value==='string'?value:JSON.stringify(value,null,2));toast('已复制');}catch{toast('复制失败，请使用导出文件',true);}}
function exportCsv(){if(!dataRecord.value)return;const value=dataRecord.value.value;const url=URL.createObjectURL(new Blob([csvForRows(value.fields,value.rows)],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='testpilot-test-data.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function time(value:string){return new Date(value).toLocaleString();}
onActivated(()=>{readTab();load();});window.addEventListener('hashchange',readTab);
onBeforeUnmount(()=>{controller?.abort();delete busyTasks.ai;window.removeEventListener('hashchange',readTab);});
</script>
<template><div class="page ai-page">
  <div class="page-heading"><div><div class="eyebrow">REQUIREMENTS → TESTS → EVIDENCE</div><h1>AI 中心</h1><p>让模型理解需求，让测试证据支撑判断。当前项目：{{project?.name||'通用工作区'}}。</p></div><a :href="aiSettingsRoute()" class="ai-engine-pill"><Icon name="ai" :size="17" /><div><strong>{{provider}}</strong><small>{{engine.model||'正在读取配置'}}</small></div><Icon name="chevron" :size="14" /></a></div>
  <div v-if="checking||loading" class="inline-note"><Icon name="loader" class="spin" />正在检查 AI 配置与项目上下文…</div>
  <template v-if="!checking&&state"><nav class="ai-tabs" aria-label="AI 功能"><button v-for="item in tabs" :key="item[0]" :class="{active:tab===item[0]}" @click="setTab(item[0]!)"><Icon :name="item[2]!" :size="17" />{{item[1]}}</button></nav>
  <div v-if="error" class="error-banner" role="alert">{{error}}</div>
  <div v-if="tab==='chat'" class="ai-chat-layout"><section class="card ai-chat-card"><div class="ai-section-heading"><div><h2>和测试助手一起推敲</h2><p>对话按当前账号与项目保存，模型不会自动执行或修改测试。</p></div><button class="icon-button" aria-label="清空 AI 对话" :disabled="working||!chat.length" @click="clearChat"><Icon name="trash" /></button></div><div ref="messagesEl" class="ai-messages" aria-live="polite"><div v-if="!chat.length&&!pending" class="ai-welcome"><div class="ai-orb"><Icon name="ai" :size="30" /></div><h2>从一个具体的测试问题开始</h2><p>描述需求、追问失败原因，或让模型解读当前项目的执行证据。</p><div class="ai-start-prompts"><button @click="shortcut('project','请帮我梳理当前项目应优先补充的测试场景，并说明依据。')">梳理测试重点<Icon name="arrow" :size="14" /></button><button @click="shortcut('recentFailure','请分析最近失败的测试，区分已知证据、可能原因和下一步验证。')">分析最近失败<Icon name="arrow" :size="14" /></button><button @click="shortcut('latestReport','请总结最近执行结果，说明通过情况、失败线索和缺失的数据。')">总结执行结果<Icon name="arrow" :size="14" /></button></div></div><template v-for="item in chat" :key="item.id"><div class="ai-chat-message user"><span class="message-role">你</span><p>{{item.value.question}}</p></div><div class="ai-chat-message assistant"><span class="message-role"><Icon name="ai" :size="14" />{{item.model}}</span><p>{{item.value.answer}}</p><div class="message-meta"><time>{{time(item.createdAt)}}</time><button class="text-button" @click="copy(item.value.answer)">复制</button></div></div></template><template v-if="pending"><div class="ai-chat-message user"><span class="message-role">你</span><p>{{pending}}</p></div><div class="ai-chat-message assistant"><span class="message-role"><Icon name="loader" class="spin" :size="15" />正在等待 {{provider}} 响应…</span></div></template></div><form class="ai-composer" @submit.prevent="send"><label class="ai-context-select">附加上下文<select v-model="contextMode" aria-label="AI 对话上下文" :disabled="working"><option value="project">当前项目证据</option><option value="recentFailure">失败分析</option><option value="latestReport">执行总结</option><option value="none">仅本次问题与对话</option></select></label><textarea v-model="message" aria-label="AI 问题" maxlength="8000" placeholder="例如：登录接口返回 200，但 token 断言失败，应如何排查？" :disabled="working" @keydown.enter.exact.prevent="send"></textarea><div><span>Enter 发送 · Shift+Enter 换行</span><button class="button primary" :disabled="working||!message.trim()"><Icon :name="busy?'loader':'send'" :class="{spin:busy}" />{{busy?'回答中…':'发送'}}</button></div></form></section><aside class="ai-side"><section class="card ai-panel"><div class="eyebrow">PROJECT CONTEXT</div><h2>这次分析基于什么</h2><div class="ai-context-counts"><div><strong>{{evidence?.counts.apiCases||0}}</strong><span>接口用例</span></div><div><strong>{{evidence?.counts.uiCases||0}}</strong><span>UI 用例</span></div><div><strong>{{evidence?.counts.executions||0}}</strong><span>近期执行</span></div></div><p>附加经后端筛选的项目记录，环境凭据会被脱敏。没有执行数据时，助手会说明信息不足。</p><button class="text-button" @click="setTab('risk')">查看证据与风险<Icon name="arrow" :size="14" /></button></section><section class="card ai-panel"><h2>从回答走向测试</h2><p>需要形成测试资产时，使用结构化生成；生成结果经过校验，保存前由你核对。</p><button class="ai-capability" @click="setTab('cases')"><Icon name="layers" /><span><strong>用例生成</strong><small>接口 / UI · 预览后入库</small></span><Icon name="chevron" :size="14" /></button><button class="ai-capability" @click="setTab('data')"><Icon name="database" /><span><strong>测试数据</strong><small>格式与校验位 · CSV / JSON</small></span><Icon name="chevron" :size="14" /></button></section></aside></div>
  <div v-if="tab==='cases'" class="ai-generation-layout"><section class="card ai-panel ai-input-panel"><div class="ai-section-heading"><div><h2>把需求变成测试场景</h2><p>描述业务规则，或填写页面 URL 分析真实页面元素。</p></div><Icon name="layers" :size="23" /></div><label class="field">需求描述 / 页面 URL<textarea v-model="requirement" aria-label="用例生成需求" maxlength="12000" placeholder="写明接口地址、输入、预期行为，或粘贴完整网页 URL。没有提供的契约与选择器会标记为待补充。" :disabled="working"></textarea></label><div class="two-fields"><label class="field">用例类型<select v-model="caseType" aria-label="AI 用例类型" :disabled="working"><option value="auto">自动判断</option><option value="api">接口测试</option><option value="ui">UI 自动化</option></select></label><label class="field">生成数量<select v-model.number="caseCount" aria-label="AI 用例数量" :disabled="working"><option v-for="n in [1,3,6,10]" :key="n" :value="n">{{n}} 条</option></select></label></div><div class="config-actions"><button class="button primary" :disabled="working||!requirement.trim()" @click="generateCases"><Icon :name="busy?'loader':'ai'" :class="{spin:busy}" />{{busy?'生成中…':'生成用例'}}</button><button class="button" :disabled="working" @click="requirement=''">清空输入</button></div><p v-if="stage" class="inline-note"><Icon name="loader" class="spin" :size="16" />{{stage}}</p><div class="ai-input-help"><Icon name="globe" :size="18" /><p>填写页面 URL 且选择自动 / UI 时，平台先调用 Playwright 提取实际交互元素。模型生成的用例不会自动执行。</p></div><div v-if="!project" class="inline-note">当前未选择项目，可生成预览；<a href="#/projects">创建项目后再保存</a>。</div><div v-if="caseRecord" class="ai-record-meta">最近生成：{{time(caseRecord.createdAt)}} · {{caseRecord.model}}</div></section><section class="ai-case-results"><div class="section-title"><div><h2>待核对的用例 <span class="badge soft">{{cases.length}}</span></h2><p class="muted help">保存到现有项目集合，不会自动运行。</p></div><button v-if="cases.length" class="button small" :disabled="working||!selected.length||!project" @click="importCases(selected)">保存所选 {{selected.length}} 条</button></div><div v-if="!cases.length" class="card ai-empty"><Icon name="layers" :size="32" /><h3>先明确需求，再生成测试</h3><p>预览名称、优先级、预期结果与需要补充的假设。</p></div><label v-if="cases.length" class="checkbox-label ai-select-all"><input v-model="allSelected" type="checkbox" :disabled="working" />选择尚未保存的用例</label><article v-for="item in cases" :key="item.id" class="card ai-case"><div class="section-title"><label class="checkbox-label"><input v-model="selected" type="checkbox" :value="item.id" :disabled="working||imported.includes(item.id)" /><h3>{{item.name}}</h3></label><span class="badge soft">{{item.priority}} · {{typeLabel[item.type]}}</span></div><p>{{item.description}}</p><dl><dt>前置条件</dt><dd>{{item.preconditions.join('；')||'未指定'}}</dd><dt>预期结果</dt><dd>{{item.expected}}</dd></dl><div class="ai-review-notes"><Icon name="alert" :size="15" /><ul><li v-for="note in item.notes" :key="note">{{note}}</li></ul></div><details><summary>查看请求 / 步骤配置</summary><pre class="code-output">{{JSON.stringify(item.draft,null,2)}}</pre></details><div class="section-title"><span class="muted help">{{imported.includes(item.id)?'已保存到项目':'AI 生成 · 需人工核对'}}</span><button class="text-button" :disabled="working||imported.includes(item.id)||!project" @click="importCases([item.id])">{{imported.includes(item.id)?'已保存':'保存此用例'}}</button></div></article></section></div>
  <div v-if="tab==='data'" class="ai-generation-layout"><section class="card ai-panel ai-input-panel"><div class="ai-section-heading"><div><h2>测试数据工厂</h2><p>AI 识别字段语义，Java 处理格式与校验位。</p></div><Icon name="database" :size="23" /></div><label class="field">字段名称（逗号分隔）<textarea v-model="fields" aria-label="测试数据字段" maxlength="500" :disabled="working"></textarea></label><div class="two-fields"><label class="field">数据模式<select v-model="dataMode" aria-label="测试数据模式" :disabled="working"><option value="VALID">有效格式</option><option value="BOUNDARY">边界样本</option><option value="INVALID">非法样本</option></select></label><label class="field">生成数量<select v-model.number="dataCount" aria-label="测试数据数量" :disabled="working"><option v-for="n in [1,5,10,20]" :value="n" :key="n">{{n}} 行</option></select></label></div><button class="button primary" :disabled="working||!fields.trim()" @click="generateData"><Icon :name="busy?'loader':'ai'" :class="{spin:busy}" />{{busy?'生成中…':'生成数据'}}</button><div class="ai-input-help"><Icon name="check" :size="18" /><p>身份证处理校验位，银行卡处理 Luhn 校验；邮箱使用测试域名。边界值依通用假设生成，仍需核对具体业务规则。</p></div><p class="muted help">所有内容均为虚构测试样本，不代表真实身份、有效账号或可用银行卡。</p></section><section class="card ai-panel ai-data-results"><div class="section-title"><div><h2>结构化数据</h2><p class="muted help">{{dataRecord?`${dataRecord.value.rows.length} 行 · ${dataRecord.model}`:'尚未生成'}}</p></div><div v-if="dataRecord" class="ai-result-tools"><button class="icon-button" aria-label="复制测试数据" @click="copy(dataRecord.value.rows)"><Icon name="copy" /></button><button class="button small" @click="exportCsv">CSV</button><button class="button small" @click="downloadJson(dataRecord.value.rows,'testpilot-test-data.json')">JSON</button></div></div><div v-if="!dataRecord" class="ai-empty"><Icon name="database" :size="32" /><h3>数据将显示在这里</h3><p>支持表格预览、复制、CSV 与 JSON 导出。</p></div><template v-else><div class="ai-view-switch"><button :class="{active:dataView==='table'}" @click="dataView='table'">表格</button><button :class="{active:dataView==='json'}" @click="dataView='json'">JSON</button></div><div v-if="dataView==='table'" class="table-scroll ai-data-table"><table><thead><tr><th v-for="f in dataRecord.value.fields" :key="f">{{f}}</th></tr></thead><tbody><tr v-for="(row,i) in dataRecord.value.rows" :key="i"><td v-for="f in dataRecord.value.fields" :key="f">{{row[f]===''?'（空值）':row[f]}}</td></tr></tbody></table></div><pre v-else class="code-output">{{JSON.stringify(dataRecord.value.rows,null,2)}}</pre><p class="ai-record-meta">{{dataRecord.value.note}}</p><div class="ai-type-tags"><span v-for="(kind,key) in dataRecord.value.types" :key="key">{{key}} <code>{{kind}}</code></span></div></template></section></div>
  <div v-if="tab==='risk'" class="ai-risk-layout"><section class="card ai-panel"><div class="ai-section-heading"><div><h2>质量证据概览</h2><p>读取当前项目最近可用的执行产物，规则与来源可核对。</p></div><button class="button small" :disabled="working||loading" @click="load"><Icon name="reset" :size="15" />刷新证据</button></div><article v-for="item in dimensions" :key="item.id" class="ai-risk-dimension"><div class="section-title"><h3>{{item.label}}</h3><span :class="['badge',item.level==='HIGH'?'bad':item.level==='NO_DATA'?'neutral':'soft']">{{labels[item.level]}}</span></div><div class="ai-risk-bar"><span :style="{width:item.score===null?'0%':`${item.score}%`}" :class="item.level"></span></div><p>{{item.samples}} 条采样<span v-if="item.score!==null"> · 观察指标 {{item.score}} / 100</span></p><ul v-if="item.evidence.length"><li v-for="line in item.evidence" :key="line">{{line}}</li></ul><p v-else class="muted">{{item.level==='NO_DATA'?'没有可读取的执行证据，不判断为低风险。':'当前记录未发现失败，不代表全面通过。'}}</p><details><summary>指标依据</summary><p>{{item.rule}}</p></details></article><div class="ai-evidence-links"><a href="#/perf">性能测试</a><a href="#/security">安全基线</a><a href="#/compat">兼容性矩阵</a><a href="#/unit">单元测试</a></div></section><aside class="ai-side"><section class="card ai-panel"><div class="ai-section-heading"><div><h2>让模型解读证据</h2><p>识别优先事项、推断边界与补测方向。</p></div><Icon name="ai" /></div><button class="button primary" :disabled="working||(!evidence?.runs.length&&!evidence?.requests.length)" @click="interpret"><Icon :name="busy?'loader':'ai'" :class="{spin:busy}" />{{busy?'正在解读…':'生成改进建议'}}</button><p v-if="!evidence?.runs.length&&!evidence?.requests.length" class="muted help ai-record-meta">先执行测试，再进行证据分析。</p></section><section v-if="riskRecord" class="card ai-panel ai-risk-advice"><h2>上次分析</h2><p class="ai-record-meta">{{time(riskRecord.createdAt)}} · {{riskRecord.model}}<br>基于生成时的证据快照，执行更新后请重新分析。</p><p class="ai-summary">{{riskRecord.value.summary}}</p><article v-for="(item,i) in riskRecord.value.actions" :key="i"><span class="badge soft">{{item.priority}}</span><h3>{{item.title}}</h3><p>{{item.reason}}</p><p><strong>验证：</strong>{{item.verification}}</p></article><div v-if="riskRecord.value.gaps.length" class="ai-review-notes"><ul><li v-for="item in riskRecord.value.gaps" :key="item">{{item}}</li></ul></div><button class="text-button" @click="downloadJson(riskRecord,'testpilot-risk-analysis.json')">导出分析与证据</button></section><section class="ai-scope-note"><Icon name="alert" :size="17" /><div><p v-for="line in evidence?.limitations" :key="line">{{line}}</p></div></section></aside></div>
  </template><div v-else-if="!loading&&error" class="error-banner" role="alert">{{error}} <button class="text-button" @click="load">重新连接</button></div>
</div></template>
